import copy

TABLES = ['cases', 'cause_versions', 'shipment_counts', 'channel_rules']

def development_triangle(snapshot, options):
    rows = snapshot['cases']
    causes = {r['case_id'] for r in snapshot['cause_versions']}
    ages = [r['reported_week'] - r['occurred_week'] for r in rows]
    return {'cases': len(rows), 'with_cause': len(causes & {r['case_id'] for r in rows}),
            'channels': sorted({r['channel'] for r in rows}),
            'delay_range': [min(ages), max(ages)] if ages else None,
            'shipment_weeks': len(snapshot['shipment_counts'])}

